        o+=T(x0+75,14,tit,'t-s mu')
        fa=lambda v:str(v).replace(".",",")
        o+=f'<rect x="{x0}" y="24" width="{a*30}" height="24" rx="6" class="bxa"/>'+TL(x0+(8 if a*30>=70 else a*30+6),40,f'A: {fa(a)} В','t-s')
